// ─── File: src/main/java/com/bank/recon/service/ChunkedQueryService.java ───
package com.bank.recon.service;

import com.bank.recon.dto.ReconReport;
import com.bank.recon.model.Trade;
import com.bank.recon.repository.TradeRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.*;
import java.util.stream.IntStream;

@Service
@RequiredArgsConstructor
@Slf4j
public class ChunkedQueryService {

    private final TradeRepository tradeRepo;

    @Value("${recon.chunk-size:500}")
    private int chunkSize;

    // ═══ APPROACH 1: NAIVE — one huge IN clause (dangerous!) ═══
    @Transactional(readOnly = true)
    public ReconReport fetchNaive(List<String> ids) {
        long start = System.currentTimeMillis();

        // (Caution) This generates: WHERE trade_id IN (?, ?, ?, ... × ids.size())
        // Oracle: ORA-01795 if > 1000. PostgreSQL: slow if > a few thousand.
        List<Trade> trades = tradeRepo.findByTradeIdIn(ids);

        long duration = System.currentTimeMillis() - start;
        BigDecimal total = trades.stream().map(Trade::getAmount)
            .reduce(BigDecimal.ZERO, BigDecimal::add);

        log.info("[NAIVE] {} IDs → {} trades in {}ms (1 query with {} params!)",
            ids.size(), trades.size(), duration, ids.size());

        return new ReconReport("NAIVE (one huge IN)", ids.size(), trades.size(),
            duration, 1, total,
            "Single query with " + ids.size() + " params. Oracle limit: 1000. Cache-busting.");
    }

    // ═══ APPROACH 2: CHUNKED — break into batches of 500 ═══
    @Transactional(readOnly = true)
    public ReconReport fetchChunked(List<String> ids) {
        long start = System.currentTimeMillis();

        List<Trade> allTrades = new ArrayList<>();
        List<List<String>> chunks = partition(ids, chunkSize);
        int queryCount = 0;

        for (List<String> chunk : chunks) {
            allTrades.addAll(tradeRepo.findByTradeIdIn(chunk));
            queryCount++;
        }

        long duration = System.currentTimeMillis() - start;
        BigDecimal total = allTrades.stream().map(Trade::getAmount)
            .reduce(BigDecimal.ZERO, BigDecimal::add);

        log.info("[CHUNKED] {} IDs → {} chunks of {} → {} trades in {}ms",
            ids.size(), queryCount, chunkSize, allTrades.size(), duration);

        return new ReconReport("CHUNKED (batches of " + chunkSize + ")",
            ids.size(), allTrades.size(), duration, queryCount, total,
            queryCount + " queries × " + chunkSize + " params each. Plan cached and reused.");
    }

    // ═══ APPROACH 3: SERVER-SIDE FILTER (best design) ═══
    @Transactional(readOnly = true)
    public ReconReport fetchServerSide() {
        long start = System.currentTimeMillis();

        // No ID list needed! The DB filters on its own.
        List<Trade> trades = tradeRepo.findByStatusAndSettlementDate("PENDING", LocalDate.now());

        long duration = System.currentTimeMillis() - start;
        BigDecimal total = trades.stream().map(Trade::getAmount)
            .reduce(BigDecimal.ZERO, BigDecimal::add);

        log.info("[SERVER-SIDE] status=PENDING, date=today → {} trades in {}ms (1 query, 2 params!)",
            trades.size(), duration);

        return new ReconReport("SERVER-SIDE FILTER",
            0, trades.size(), duration, 1, total,
            "WHERE status='PENDING' AND date=today. No ID shipping. 2 params. Index-friendly.");
    }

    // Generate test IDs
    public List<String> generateTestIds(int count) {
        return IntStream.rangeClosed(1, count)
            .mapToObj(i -> "TRD-" + String.format("%05d", i))
            .toList();
    }

    // Simple partition utility (like Guava Lists.partition)
    private <T> List<List<T>> partition(List<T> list, int size) {
        List<List<T>> partitions = new ArrayList<>();
        for (int i = 0; i < list.size(); i += size) {
            partitions.add(list.subList(i, Math.min(i + size, list.size())));
        }
        return partitions;
    }
}
