// ─── File: src/main/java/com/bank/recon/controller/ReconController.java ───
package com.bank.recon.controller;

import com.bank.recon.dto.ReconReport;
import com.bank.recon.service.ChunkedQueryService;
import lombok.RequiredArgsConstructor;
import org.springframework.web.bind.annotation.*;
import java.util.Map;

@RestController
@RequestMapping("/api/v1/recon")
@RequiredArgsConstructor
public class ReconController {

    private final ChunkedQueryService service;

    @GetMapping("/naive")
    public ReconReport naive(@RequestParam(defaultValue = "100") int count) {
        return service.fetchNaive(service.generateTestIds(count));
    }

    @GetMapping("/chunked")
    public ReconReport chunked(@RequestParam(defaultValue = "100") int count) {
        return service.fetchChunked(service.generateTestIds(count));
    }

    @GetMapping("/server-side")
    public ReconReport serverSide() {
        return service.fetchServerSide();
    }

    @GetMapping("/compare")
    public Map<String, ReconReport> compare(@RequestParam(defaultValue = "100") int count) {
        var ids = service.generateTestIds(count);
        return Map.of(
            "naive", service.fetchNaive(ids),
            "chunked", service.fetchChunked(ids),
            "serverSide", service.fetchServerSide());
    }
}
