// ─── File: src/test/java/com/bank/recon/service/ChunkedQueryTest.java ───
package com.bank.recon.service;

import org.junit.jupiter.api.Test;
import java.util.*;
import static org.assertj.core.api.Assertions.*;

class ChunkedQueryTest {

    @Test
    void partitionSplitsCorrectly() {
        List<Integer> list = List.of(1, 2, 3, 4, 5, 6, 7);
        List<List<Integer>> chunks = partition(list, 3);
        assertThat(chunks).hasSize(3);
        assertThat(chunks.get(0)).containsExactly(1, 2, 3);
        assertThat(chunks.get(1)).containsExactly(4, 5, 6);
        assertThat(chunks.get(2)).containsExactly(7);
    }

    @Test
    void partitionHandlesExactMultiple() {
        List<Integer> list = List.of(1, 2, 3, 4, 5, 6);
        List<List<Integer>> chunks = partition(list, 3);
        assertThat(chunks).hasSize(2);
    }

    @Test
    void partitionHandlesSmallerThanChunk() {
        List<Integer> list = List.of(1, 2);
        List<List<Integer>> chunks = partition(list, 500);
        assertThat(chunks).hasSize(1);
        assertThat(chunks.get(0)).containsExactly(1, 2);
    }

    @Test
    void partitionHandlesEmpty() {
        List<List<Integer>> chunks = partition(List.of(), 500);
        assertThat(chunks).isEmpty();
    }

    @Test
    void chunkSizeOf500Keeps10KManageable() {
        // 10K IDs ÷ 500 per chunk = 20 queries
        int totalIds = 10000;
        int chunkSize = 500;
        int expectedChunks = (totalIds + chunkSize - 1) / chunkSize;
        assertThat(expectedChunks).isEqualTo(20);
    }

    @Test
    void oracleLimitIs1000() {
        // Oracle: ORA-01795: maximum number of expressions in a list is 1000
        int oracleLimit = 1000;
        int safeChunkSize = 500; // well under limit
        assertThat(safeChunkSize).isLessThan(oracleLimit);
    }

    private <T> List<List<T>> partition(List<T> list, int size) {
        List<List<T>> partitions = new ArrayList<>();
        for (int i = 0; i < list.size(); i += size) {
            partitions.add(list.subList(i, Math.min(i + size, list.size())));
        }
        return partitions;
    }
}
